"""Generate the market scripts from SIMULATION-MATHS.md section 7.

Section 7 is the human-readable source. This generator is the single path from the doc to
the engine. It writes:

  data/market-script.json   the scripts as data
  engine/market-script.js   the same data as an ES module, so the engine imports it unchanged
                            in Node and a browser

The scripts are authored month-by-month data, a named exception to ENGINE.md rule 1
recorded in section 12: they do not live in the constants table.

Usage: python scripts/export_market_script.py
"""

import json
import re
import sys
from decimal import Decimal
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DOC_PATH = ROOT / "SIMULATION-MATHS.md"
JSON_PATH = ROOT / "data" / "market-script.json"
MODULE_PATH = ROOT / "engine" / "market-script.js"

# Section 7 table marker -> (engine key, instrument name used in the lesson windows table)
SCRIPTS = {
    "**Broad equity script.**": ("equity", "Broad equity"),
    "**Small cap script.**": ("small_cap", "Small cap equity"),
}
WINDOWS_MARKER = "**Lesson windows.**"


def section(text, number):
    match = re.search(rf"^## {number}\..*?(?=^## )", text, re.S | re.M)
    if not match:
        sys.exit(f"Section {number} not found")
    return match.group(0)


def first_table_after(text, marker):
    start = text.find(marker)
    if start < 0:
        sys.exit(f"{marker} not found in section 7")
    rows, in_table = [], False
    for line in text[start:].splitlines():
        if line.startswith("|"):
            in_table = True
            cells = [c.strip() for c in line.strip("|").split("|")]
            if not set("".join(cells)) <= set("-: "):
                rows.append(cells)
        elif in_table:
            break
    return rows[1:]  # drop the header


def month_range(cell):
    match = re.fullmatch(r"(\d+) to (\d+)", cell)
    if not match:
        sys.exit(f"Bad month range: {cell!r}")
    return int(match.group(1)), int(match.group(2))


def percent(cell):
    # Decimal, so "+0.9%" becomes exactly the shortest float for 0.009, not 0.9 / 100
    return float(Decimal(cell.replace("%", "").replace("+", "")) / 100)


def read_market_script(doc_path=DOC_PATH):
    s7 = section(doc_path.read_text(encoding="utf-8"), 7)
    instruments, names = {}, {}
    for marker, (key, name) in SCRIPTS.items():
        regimes, drift = [], []
        expected_start = 1
        for months, regime, monthly, why in first_table_after(s7, marker):
            first, last = month_range(months)
            if first != expected_start:
                sys.exit(f"{name}: months {months} do not follow on from month {expected_start - 1}")
            expected_start = last + 1
            authored = monthly != "n/a"
            regimes.append({
                "months": [first, last], "regime": regime,
                "monthly_drift": percent(monthly) if authored else None, "why": why,
            })
            if authored:
                if len(drift) != first - 1:
                    sys.exit(f"{name}: authored months resume after a gap at {months}")
                drift.extend([percent(monthly)] * (last - first + 1))
        instruments[key] = {
            "name": name,
            "authored_through": len(drift),
            "monthly_drift": drift,
            "regimes": regimes,
        }
        names[name] = key

    windows = []
    for window, instrument, months, direction, lesson in first_table_after(s7, WINDOWS_MARKER):
        if instrument not in names:
            sys.exit(f"{window}: unknown instrument {instrument!r}")
        key = names[instrument]
        first, last = month_range(months)
        if last > instruments[key]["authored_through"]:
            sys.exit(f"{window}: months {months} go beyond the authored script")
        windows.append({
            "name": window.strip("`"), "instrument": key, "months": [first, last],
            "direction": direction.lower(), "lesson": lesson,
        })
    return {"source": "SIMULATION-MATHS.md section 7", "instruments": instruments, "lesson_windows": windows}


def main():
    script = read_market_script()
    payload = json.dumps(script, ensure_ascii=False, indent=2)
    JSON_PATH.write_text(payload + "\n", encoding="utf-8", newline="\n")
    MODULE_PATH.write_text(
        "// Generated by scripts/export_market_script.py from SIMULATION-MATHS.md section 7.\n"
        "// Do not edit by hand. Edit section 7 and regenerate.\n\n"
        f"const MARKET_SCRIPT = {payload};\n\nexport default MARKET_SCRIPT;\n",
        encoding="utf-8",
        newline="\n",
    )
    summary = ", ".join(f"{k} months 1 to {v['authored_through']}" for k, v in script["instruments"].items())
    print(f"Wrote {JSON_PATH.relative_to(ROOT)} and {MODULE_PATH.relative_to(ROOT)}: {summary}, "
          f"{len(script['lesson_windows'])} lesson windows")


if __name__ == "__main__":
    main()
